// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address account, uint256 id, uint256 amount, string memory name_, string memory tokenURI, bool finiteSupply, bool transferable, uint256 itemsRemaining, uint256 itemPrice, uint16 dailyAllowance) public {
        // Bound inputs to reasonable ranges
        vm.assume(account != address(0));
        vm.assume(itemsRemaining < type(uint256).max / 2);
        vm.assume(id < 100);

        // First make c an admin
        c.adjustAdminAccess(address(this), true);

        // Create a game item
        c.createGameItem(name_, tokenURI, finiteSupply, transferable, itemsRemaining, itemPrice, dailyAllowance);

        // The balance should be 0 for any account that hasn't minted
        uint256 balance = c.balanceOf(account, 0);

        // General rule: balanceOf should return 0 for any account that hasn't received tokens
        assertTrue(balance == 0, "balanceOf should return 0 for non-owners");
    }
}

